use serde_json::{Value, json};
pub fn tools() -> Vec<Value> {
    vec![
        json!({"name":"search_history","description":"Search what this team's agents, including finished ones, wrote, ran, got back and were told, newest first, with who and when. Use it before building something that may exist already, or to find who knows about something (then ask them with send_agent_message). Costs no model call.","inputSchema":{"type":"object","properties":{"query":{"type":"string","description":"Words to find, at least 3 characters"},"agent":{"type":"string","description":"Only this agent's history (name or id)"}},"required":["query"]}}),
        json!({"name":"record_lesson","description":"Record a lesson for this team: something that cost you a wrong turn and that other agents should not repeat, in one or two sentences (what happened, what to do instead). Teammates already working are told it with their next message; later agents get it in their briefing. When a person confirms it, it is kept with the project for later teams too.","inputSchema":{"type":"object","properties":{"lesson":{"type":"string"},"kind":{"type":"string","enum":["lesson","constraint"],"description":"constraint: a rule every agent must follow in this project (such as never using float for money); lesson (default): a tip"}},"required":["lesson"]}}),
        json!({"name":"spawn_agent","description":"Create a managed child agent, visible on the live board and stopped with its parent. Each child is a full agent whose usage counts against the same plan: spawn only for large, independent work, never to split up reading. Inherits this agent's model, folder and permissions. Use for bounded, independent help; do not replace configured teammates. Reuse request_id for retries. The team may set limits on how many agents it has and how many levels of children; a refusal names the limit.","inputSchema":{"type":"object","properties":{"request_id":{"type":"string"},"name":{"type":"string"},"task":{"type":"string"}},"required":["request_id","name","task"]}}),
        json!({"name":"send_agent_message","description":"Message another agent in this project, including engine feature/support requests and subagent results. It is queued if busy; does not interrupt. Use team_status for exact recipient IDs. Include context, artifact revision, desired response and your own ID. Reuse request_id for retries.","inputSchema":{"type":"object","properties":{"request_id":{"type":"string"},"to":{"type":"string"},"text":{"type":"string"},"fyi":{"type":"boolean","description":"A status note that needs no action now: an idle receiver gets it with its next message instead of being woken. Never for results, questions or requests."}},"required":["request_id","to","text"]}}),
        json!({"name":"team_status","description":"Read current project agents, parent relationships, activity, lifecycle and stop controls. An idle open session is not active work.","inputSchema":{"type":"object","properties":{}}}),
    ]
}
